if (!doc.containsKey("exception.stacktrace") || doc["exception.stacktrace"].isEmpty()
        || !doc.containsKey("exception.type") || doc["exception.type"].isEmpty()) {
    return;
}
String exceptionType = doc["exception.type"].value;
String stacktrace = doc["exception.stacktrace"].value;
String[] lines = stacktrace.splitOnToken(String.valueOf((char) 10));

// Binary Images: "<start> - <end> [+]<name> <arch>  <<uuid>> <path>"
Map systemImages = new HashMap();
boolean inImages = false;
for (String line : lines) {
    if (line == "Binary Images:") {
        inImages = true;
    } else if (inImages) {
        int dash = line.indexOf(" - ");
        int uuid = line.indexOf("  <");
        int path = line.indexOf("> ");
        if (dash < 0 || uuid < 0 || path < 0) {
            continue;
        }
        String image = line.substring(dash + 3, uuid).trim();
        image = image.substring(image.indexOf(" ") + 1).trim();
        if (image.startsWith("+")) {
            image = image.substring(1);
        }
        image = image.substring(0, image.lastIndexOf(" "));
        String imagePath = line.substring(path + 2);
        systemImages.put(image, imagePath.contains("/System/Library/") || imagePath.contains("/usr/lib/"));
    }
}

// The throw site of an uncaught exception, else the crashed thread.
String section = "Thread ";
for (String line : lines) {
    if (line == "Last Exception Backtrace:") {
        section = line;
    }
}
boolean inSection = false;
for (String line : lines) {
    if (!inSection) {
        inSection = section == "Thread " ? line.startsWith("Thread ") && line.endsWith(" Crashed:") : line == section;
        continue;
    }
    if (line.isEmpty()) {
        return;
    }
    // Frame: "<index> <image> 0x<address> 0x<load address> + <offset>"
    int address = line.indexOf(" 0x");
    int offset = line.lastIndexOf(" + ");
    if (address < 0 || offset < 0) {
        continue;
    }
    int start = 0;
    while (start < address && Character.isDigit(line.charAt(start))) {
        start++;
    }
    String image = line.substring(start, address).trim();
    if (systemImages.containsKey(image) && !systemImages.get(image)) {
        emit(String.valueOf((exceptionType + "|" + image + "+" + line.substring(offset + 3)).hashCode()).encodeBase64());
        return;
    }
}

if(doc.containsKey("span.name") && !doc["span.name"].isEmpty()) {
  emit("[Span] - " + $("span.name", ""));
} else if (doc.containsKey("message")) {
  if (doc.containsKey("event_name") && !doc["event_name"].isEmpty()) {
    emit("[Log] - " + $("event_name", ""));
  } else {
    emit("[Log] - " + $("message", ""));
  }
}

